  1	//! Ear-clipping polygon triangulator.
  2	//!
  3	//! A `std`-only port of the `mapbox::earcut` 2.2.x algorithm: build a circular
  4	//! doubly-linked list from the outer ring, splice holes in as bridges, then clip
  5	//! ears one by one. When no ear can be found the algorithm escalates through
  6	//! three fallbacks — filter collinear points, cure local self-intersections,
  7	//! and finally split the ring on a valid diagonal — which is what makes a
  8	//! self-intersecting input such as a spiral triangulable at all.
  9	//!
 10	//! The triangle indices are emitted in exactly the order the reference
 11	//! implementation emits them; the fallback passes are order-sensitive, so the
 12	//! control flow is kept structurally identical rather than idiomatically
 13	//! restructured.
 14	
 15	pub mod geom;
 16	pub mod node;
 17	pub mod zorder;
 18	
 19	use node::{Node, NIL};
 20	
 21	/// Triangulate a polygon given as a list of rings (outer ring first, holes after)
 22	/// and return a flat list of triangle vertex indices into the concatenated rings.
 23	pub fn earcut(points: &[Vec<[f64; 2]>]) -> Vec<u32> {
 24	    let mut earcut = Earcut::new();
 25	    earcut.run(points);
 26	    earcut.indices
 27	}
 28	
 29	pub struct Earcut {
 30	    pub indices: Vec<u32>,
 31	    pub vertices: usize,
 32	
 33	    /// Arena backing the linked list; `usize` indices replace the original `Node*`.
 34	    pub(crate) nodes: Vec<Node>,
 35	
 36	    hashing: bool,
 37	    min_x: f64,
 38	    max_x: f64,
 39	    min_y: f64,
 40	    max_y: f64,
 41	    inv_size: f64,
 42	}
 43	
 44	impl Default for Earcut {
 45	    fn default() -> Self {
 46	        Self::new()
 47	    }
 48	}
 49	
 50	impl Earcut {
 51	    pub fn new() -> Self {
 52	        Earcut {
 53	            indices: Vec::new(),
 54	            vertices: 0,
 55	            nodes: Vec::new(),
 56	            hashing: false,
 57	            min_x: 0.0,
 58	            max_x: 0.0,
 59	            min_y: 0.0,
 60	            max_y: 0.0,
 61	            inv_size: 0.0,
 62	        }
 63	    }
 64	
 65	    /// Allocate a node in the arena and return its index.
 66	    pub(crate) fn construct(&mut self, i: u32, x: f64, y: f64) -> usize {
 67	        self.nodes.push(Node::new(i, x, y));
 68	        self.nodes.len() - 1
 69	    }
 70	
 71	    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
 72	        // reset
 73	        self.indices.clear();
 74	        self.vertices = 0;
 75	        self.nodes.clear();
 76	        self.hashing = false;
 77	        self.inv_size = 0.0;
 78	
 79	        if points.is_empty() {
 80	            return;
 81	        }
 82	
 83	        // The z-order hash only pays off past a vertex count threshold; the loop
 84	        // stops early once the budget is blown, matching the reference exactly.
 85	        let mut threshold: i32 = 80;
 86	        let mut len: usize = 0;
 87	        let mut i = 0;
 88	        while threshold >= 0 && i < points.len() {
 89	            threshold -= points[i].len() as i32;
 90	            len += points[i].len();
 91	            i += 1;
 92	        }
 93	
 94	        // estimate size of nodes and indices
 95	        self.nodes.reserve(len * 3 / 2);
 96	        self.indices.reserve(len + points[0].len());
 97	
 98	        let mut outer_node = self.linked_list(&points[0], true);
 99	        if outer_node == NIL || self.nodes[outer_node].prev == self.nodes[outer_node].next {
100	            return;
101	        }
102	
103	        if points.len() > 1 {
104	            outer_node = self.eliminate_holes(points, outer_node);
105	        }
106	
107	        // if the shape is not too simple, we'll use z-order curve hash later;
108	        // calculate polygon bbox
109	        self.hashing = threshold < 0;
110	        if self.hashing {
111	            let mut p = self.nodes[outer_node].next;
112	            self.min_x = self.nodes[outer_node].x;
113	            self.max_x = self.min_x;
114	            self.min_y = self.nodes[outer_node].y;
115	            self.max_y = self.min_y;
116	            loop {
117	                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
118	                self.min_x = self.min_x.min(x);
119	                self.min_y = self.min_y.min(y);
120	                self.max_x = self.max_x.max(x);
121	                self.max_y = self.max_y.max(y);
122	                p = self.nodes[p].next;
123	                if p == outer_node {
124	                    break;
125	                }
126	            }
127	
128	            // min_x, min_y and inv_size are later used to transform coords into
129	            // integers for z-order calculation
130	            self.inv_size = (self.max_x - self.min_x).max(self.max_y - self.min_y);
131	            self.inv_size = if self.inv_size != 0.0 {
132	                32767.0 / self.inv_size
133	            } else {
134	                0.0
135	            };
136	        }
137	
138	        self.earcut_linked(outer_node, 0);
139	    }
140	
141	    /// Create a circular doubly-linked list from polygon points in the specified
142	    /// winding order.
143	    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
144	        let mut sum = 0.0;
145	        let len = points.len();
146	        let mut last = NIL;
147	
148	        // calculate original winding order of a polygon ring
149	        let mut j = if len > 0 { len - 1 } else { 0 };
150	        for i in 0..len {
151	            let p1 = &points[i];
152	            let p2 = &points[j];
153	            let p20 = p2[0];
154	            let p10 = p1[0];
155	            let p11 = p1[1];
156	            let p21 = p2[1];
157	            sum += (p20 - p10) * (p11 + p21);
158	            j = i;
159	        }
160	
161	        // link points into circular doubly-linked list in the specified winding order
162	        if clockwise == (sum > 0.0) {
163	            for i in 0..len {
164	                last = self.insert_node(self.vertices + i, &points[i], last);
165	            }
166	        } else {
167	            for i in (0..len).rev() {
168	                last = self.insert_node(self.vertices + i, &points[i], last);
169	            }
170	        }
171	
172	        if last != NIL {
173	            let next = self.nodes[last].next;
174	            if self.equals(last, next) {
175	                self.remove_node(last);
176	                last = next;
177	            }
178	        }
179	
180	        self.vertices += len;
181	
182	        last
183	    }
184	
185	    /// Create a node and optionally link it with a previous one (in a circular
186	    /// doubly-linked list).
187	    fn insert_node(&mut self, i: usize, pt: &[f64; 2], last: usize) -> usize {
188	        let p = self.construct(i as u32, pt[0], pt[1]);
189	
190	        if last == NIL {
191	            self.nodes[p].prev = p;
192	            self.nodes[p].next = p;
193	        } else {
194	            let next = self.nodes[last].next;
195	            self.nodes[p].next = next;
196	            self.nodes[p].prev = last;
197	            self.nodes[next].prev = p;
198	            self.nodes[last].next = p;
199	        }
200	
201	        p
202	    }
203	
204	    /// Eliminate colinear or duplicate points. Pass `NIL` for `end` to default it
205	    /// to `start`.
206	    fn filter_points(&mut self, start: usize, end: usize) -> usize {
207	        if start == NIL {
208	            return start;
209	        }
210	        let mut end = if end == NIL { start } else { end };
211	
212	        let mut p = start;
213	        loop {
214	            let again;
215	            let prev = self.nodes[p].prev;
216	            let next = self.nodes[p].next;
217	
218	            if !self.nodes[p].steiner && (self.equals(p, next) || self.area(prev, p, next) == 0.0) {
219	                self.remove_node(p);
220	                p = prev;
221	                end = prev;
222	
223	                if p == self.nodes[p].next {
224	                    break;
225	                }
226	                again = true;
227	            } else {
228	                p = next;
229	                again = false;
230	            }
231	
232	            if !(again || p != end) {
233	                break;
234	            }
235	        }
236	
237	        end
238	    }
