240	    /// Main ear slicing loop which triangulates a polygon (given as a linked list).
241	    fn earcut_linked(&mut self, ear: usize, pass: i32) {
242	        let mut ear = ear;
243	        if ear == NIL {
244	            return;
245	        }
246	
247	        // interlink polygon nodes in z-order
248	        if pass == 0 && self.hashing {
249	            self.index_curve(ear);
250	        }
251	
252	        let mut stop = ear;
253	
254	        // iterate through ears, slicing them one by one
255	        while self.nodes[ear].prev != self.nodes[ear].next {
256	            let prev = self.nodes[ear].prev;
257	            let next = self.nodes[ear].next;
258	
259	            let found = if self.hashing {
260	                self.is_ear_hashed(ear)
261	            } else {
262	                self.is_ear(ear)
263	            };
264	
265	            if found {
266	                // cut off the triangle
267	                self.indices.push(self.nodes[prev].i);
268	                self.indices.push(self.nodes[ear].i);
269	                self.indices.push(self.nodes[next].i);
270	
271	                self.remove_node(ear);
272	
273	                // skipping the next vertex leads to less sliver triangles
274	                ear = self.nodes[next].next;
275	                stop = ear;
276	
277	                continue;
278	            }
279	
280	            ear = next;
281	
282	            // if we looped through the whole remaining polygon and can't find any
283	            // more ears
284	            if ear == stop {
285	                if pass == 0 {
286	                    // try filtering points and slicing again
287	                    let filtered = self.filter_points(ear, NIL);
288	                    self.earcut_linked(filtered, 1);
289	                } else if pass == 1 {
290	                    // if this didn't work, try curing all small self-intersections
291	                    // locally
292	                    let filtered = self.filter_points(ear, NIL);
293	                    let cured = self.cure_local_intersections(filtered);
294	                    self.earcut_linked(cured, 2);
295	                } else if pass == 2 {
296	                    // as a last resort, try splitting the remaining polygon into two
297	                    self.split_earcut(ear);
298	                }
299	
300	                break;
301	            }
302	        }
303	    }
304	
305	    /// Check whether a polygon node forms a valid ear with adjacent nodes.
306	    fn is_ear(&self, ear: usize) -> bool {
307	        let a = self.nodes[ear].prev;
308	        let b = ear;
309	        let c = self.nodes[ear].next;
310	
311	        if self.area(a, b, c) >= 0.0 {
312	            return false; // reflex, can't be an ear
313	        }
314	
315	        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
316	        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
317	        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);
318	
319	        // now make sure we don't have other points inside the potential ear
320	        let mut p = self.nodes[c].next;
321	
322	        while p != a {
323	            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
324	            let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
325	            if self.point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
326	                && self.area(pp, p, pn) >= 0.0
327	            {
328	                return false;
329	            }
330	            p = pn;
331	        }
332	
333	        true
334	    }
