336	    /// Same as [`Earcut::is_ear`] but only visiting points whose z-order falls in
337	    /// the triangle's bounding box range.
338	    fn is_ear_hashed(&self, ear: usize) -> bool {
339	        let a = self.nodes[ear].prev;
340	        let b = ear;
341	        let c = self.nodes[ear].next;
342	
343	        if self.area(a, b, c) >= 0.0 {
344	            return false; // reflex, can't be an ear
345	        }
346	
347	        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
348	        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
349	        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);
350	
351	        // triangle bbox; min & max are calculated like this for speed
352	        let min_tx = ax.min(bx.min(cx));
353	        let min_ty = ay.min(by.min(cy));
354	        let max_tx = ax.max(bx.max(cx));
355	        let max_ty = ay.max(by.max(cy));
356	
357	        // z-order range for the current triangle bbox
358	        let min_z = self.z_order(min_tx, min_ty);
359	        let max_z = self.z_order(max_tx, max_ty);
360	
361	        // first look for points inside the triangle in increasing z-order
362	        let mut p = self.nodes[ear].next_z;
363	
364	        while p != NIL && self.nodes[p].z <= max_z {
365	            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
366	            let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
367	            if p != a
368	                && p != c
369	                && self.point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
370	                && self.area(pp, p, pn) >= 0.0
371	            {
372	                return false;
373	            }
374	            p = self.nodes[p].next_z;
375	        }
376	
377	        // then look for points in decreasing z-order
378	        p = self.nodes[ear].prev_z;
379	
380	        while p != NIL && self.nodes[p].z >= min_z {
381	            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
382	            let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
383	            if p != a
384	                && p != c
385	                && self.point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
386	                && self.area(pp, p, pn) >= 0.0
387	            {
388	                return false;
389	            }
390	            p = self.nodes[p].prev_z;
391	        }
392	
393	        true
394	    }
395	
396	    /// Go through all polygon nodes and cure small local self-intersections.
397	    fn cure_local_intersections(&mut self, start: usize) -> usize {
398	        let mut start = start;
399	        let mut p = start;
400	
401	        loop {
402	            let a = self.nodes[p].prev;
403	            let pn = self.nodes[p].next;
404	            let b = self.nodes[pn].next;
405	
406	            // a self-intersection where edge (v[i-1],v[i]) intersects (v[i+1],v[i+2])
407	            if !self.equals(a, b)
408	                && self.intersects(a, p, pn, b)
409	                && self.locally_inside(a, b)
410	                && self.locally_inside(b, a)
411	            {
412	                self.indices.push(self.nodes[a].i);
413	                self.indices.push(self.nodes[p].i);
414	                self.indices.push(self.nodes[b].i);
415	
416	                // remove two nodes involved; `pn` is still `p.next` after the first
417	                // removal, which only rewires the neighbours
418	                self.remove_node(p);
419	                self.remove_node(pn);
420	
421	                p = b;
422	                start = b;
423	            }
424	
425	            p = self.nodes[p].next;
426	            if p == start {
427	                break;
428	            }
429	        }
430	
431	        self.filter_points(p, NIL)
432	    }
433	
434	    /// Try splitting polygon into two and triangulate them independently.
435	    fn split_earcut(&mut self, start: usize) {
436	        // look for a valid diagonal that divides the polygon into two
437	        let mut a = start;
438	        loop {
439	            let an = self.nodes[a].next;
440	            let mut b = self.nodes[an].next;
441	
442	            while b != self.nodes[a].prev {
443	                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
444	                    // split the polygon in two by the diagonal
445	                    let mut c = self.split_polygon(a, b);
446	
447	                    // filter colinear points around the cuts
448	                    let a_next = self.nodes[a].next;
449	                    let a2 = self.filter_points(a, a_next);
450	                    let c_next = self.nodes[c].next;
451	                    c = self.filter_points(c, c_next);
452	
453	                    // run earcut on each half
454	                    self.earcut_linked(a2, 0);
455	                    self.earcut_linked(c, 0);
456	                    return;
457	                }
458	                b = self.nodes[b].next;
459	            }
460	            a = self.nodes[a].next;
461	            if a == start {
462	                return;
463	            }
464	        }
465	    }
466	
467	    /// Link every hole into the outer loop, producing a single-ring polygon
468	    /// without holes.
469	    fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], outer_node: usize) -> usize {
470	        let mut queue: Vec<usize> = Vec::new();
471	
472	        for ring in &points[1..] {
473	            let list = self.linked_list(ring, false);
474	            if list != NIL {
475	                if list == self.nodes[list].next {
476	                    self.nodes[list].steiner = true;
477	                }
478	                let leftmost = self.get_leftmost(list);
479	                queue.push(leftmost);
480	            }
481	        }
482	
483	        {
484	            let nodes = &self.nodes;
485	            queue.sort_by(|&a, &b| {
486	                nodes[a]
487	                    .x
488	                    .partial_cmp(&nodes[b].x)
489	                    .unwrap_or(std::cmp::Ordering::Equal)
490	            });
491	        }
492	
493	        // process holes from left to right
494	        let mut outer_node = outer_node;
495	        for hole in queue {
496	            outer_node = self.eliminate_hole(hole, outer_node);
497	        }
498	
499	        outer_node
500	    }
501	
502	    /// Find a bridge between vertices that connects a hole with an outer ring and
503	    /// link it.
504	    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
505	        let bridge = self.find_hole_bridge(hole, outer_node);
506	        if bridge == NIL {
507	            return outer_node;
508	        }
509	
510	        let bridge_reverse = self.split_polygon(bridge, hole);
511	
512	        // filter collinear points around the cuts
513	        let br_next = self.nodes[bridge_reverse].next;
514	        self.filter_points(bridge_reverse, br_next);
515	        let b_next = self.nodes[bridge].next;
516	        self.filter_points(bridge, b_next)
517	    }
518	
519	    /// David Eberly's algorithm for finding a bridge between a hole and an outer
520	    /// polygon.
521	    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
522	        let mut p = outer_node;
523	        let hx = self.nodes[hole].x;
524	        let hy = self.nodes[hole].y;
525	        let mut qx = f64::NEG_INFINITY;
526	        let mut m = NIL;
527	
528	        // find a segment intersected by a ray from the hole's leftmost vertex to
529	        // the left; segment's endpoint with lesser x will be potential connection
530	        // vertex
531	        loop {
532	            let pn = self.nodes[p].next;
533	            let (py, pny) = (self.nodes[p].y, self.nodes[pn].y);
534	            if hy <= py && hy >= pny && pny != py {
535	                let (px, pnx) = (self.nodes[p].x, self.nodes[pn].x);
536	                let x = px + (hy - py) / (pny - py) * (pnx - px);
537	                if x <= hx && x > qx {
538	                    qx = x;
539	                    m = if px < pnx { p } else { pn };
540	                    if x == hx {
541	                        // hole touches outer segment; pick leftmost endpoint
542	                        return m;
543	                    }
544	                }
545	            }
546	            p = pn;
547	            if p == outer_node {
548	                break;
549	            }
550	        }
551	
552	        if m == NIL {
553	            return NIL;
554	        }
555	
556	        // look for points inside the triangle of hole vertex, segment intersection
557	        // and endpoint; if there are no points found, we have a valid connection;
558	        // otherwise choose the vertex of the polygon with the least x
559	        let stop = m;
560	        let mut tan_min = f64::INFINITY;
561	        let mx = self.nodes[m].x;
562	        let my = self.nodes[m].y;
563	
564	        p = m;
565	        loop {
566	            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
567	            if hx >= px
568	                && px >= mx
569	                && hx != px
570	                && self.point_in_triangle(
571	                    if hy < my { hx } else { qx },
572	                    hy,
573	                    mx,
574	                    my,
575	                    if hy < my { qx } else { hx },
576	                    hy,
577	                    px,
578	                    py,
579	                )
580	            {
581	                let tan_cur = (hy - py).abs() / (hx - px); // tangential
582	
583	                if self.locally_inside(p, hole)
584	                    && (tan_cur < tan_min
585	                        || (tan_cur == tan_min
586	                            && (px > self.nodes[m].x || self.sector_contains_sector(m, p))))
587	                {
588	                    m = p;
589	                    tan_min = tan_cur;
590	                }
591	            }
592	
593	            p = self.nodes[p].next;
594	            if p == stop {
595	                break;
596	            }
597	        }
598	
599	        m
600	    }
601	}

     1	//! Node of the circular doubly-linked list the ear-clipping triangulator walks.
     2	//!
     3	//! The reference implementation links heap-allocated nodes with raw pointers.
     4	//! Here the nodes live in a single arena (`Vec<Node>`) and the links are arena
     5	//! indices, with [`NIL`] standing in for a null pointer. Indices stay valid
     6	//! across arena growth, which pointers into a `Vec` would not.
     7	
     8	/// Sentinel used where the reference implementation stores a null `Node*`.
     9	pub const NIL: usize = usize::MAX;
    10	
    11	#[derive(Clone, Copy)]
    12	pub struct Node {
    13	    /// Index of the vertex within the flattened input.
    14	    pub i: u32,
    15	    pub x: f64,
    16	    pub y: f64,
    17	
    18	    /// Previous and next vertex nodes in a polygon ring.
    19	    pub prev: usize,
    20	    pub next: usize,
    21	
    22	    /// Z-order curve value.
    23	    pub z: i32,
    24	
    25	    /// Previous and next nodes in z-order.
    26	    pub prev_z: usize,
    27	    pub next_z: usize,
    28	
    29	    /// Indicates whether this is a steiner point.
    30	    pub steiner: bool,
    31	}
    32	
    33	impl Node {
    34	    pub fn new(i: u32, x: f64, y: f64) -> Self {
    35	        Node {
    36	            i,
    37	            x,
    38	            y,
    39	            prev: NIL,
    40	            next: NIL,
    41	            z: 0,
    42	            prev_z: NIL,
    43	            next_z: NIL,
    44	            steiner: false,
