398	    /// Go through all polygon nodes and cure small local self-intersections.
399	    fn cure_local_intersections(&mut self, start: usize) -> usize {
400	        let mut start = start;
401	        let mut p = start;
402	
403	        loop {
404	            let a = self.nodes[p].prev;
405	            let pn = self.nodes[p].next;
406	            let b = self.nodes[pn].next;
407	
408	            // a self-intersection where edge (v[i-1],v[i]) intersects (v[i+1],v[i+2])
409	            if !self.equals(a, b)
410	                && self.intersects(a, p, pn, b)
411	                && self.locally_inside(a, b)
412	                && self.locally_inside(b, a)
413	            {
414	                self.indices.push(self.nodes[a].i);
415	                self.indices.push(self.nodes[p].i);
416	                self.indices.push(self.nodes[b].i);
417	
418	                // remove two nodes involved; `pn` is still `p.next` after the first
419	                // removal, which only rewires the neighbours
420	                self.remove_node(p);
421	                self.remove_node(pn);
422	
423	                p = b;
424	                start = b;
425	            }
426	
427	            p = self.nodes[p].next;
428	            if p == start {
429	                break;
430	            }
431	        }
432	
433	        self.filter_points(p, NIL)
434	    }
